window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-00d681f2ae9b1715"]={"versions": [{"id": "FIG-00d681f2ae9b1715", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Konfigurations-Metamodells (ECUC Parameter Definition) für das BSW-Modul Crypto Service Manager (CSM) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die modulare Gliederung der BSW-Konfiguration über Container-Definitionen (<code>EcucParamConfContainerDef</code>) und deren hierarchische Komposition unterhalb der Moduldefinition (<code>EcucModuleDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Csm : EcucModuleDef</strong>: Wurzel-Moduldefinition des Crypto Service Managers mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmGeneral : EcucParamConfContainerDef</strong>: Allgemeiner Konfigurationscontainer (ohne explizit angegebene Multiplizität).\n</li><li><strong>CsmJobs : EcucParamConfContainerDef</strong>: Container zur Definition kryptografischer Jobs mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmKeys : EcucParamConfContainerDef</strong>: Container für Schlüsseldefinitionen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmPrimitives : EcucParamConfContainerDef</strong>: Container für kryptografische Primitive mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>CsmQueues : EcucParamConfContainerDef</strong>: Container für CSM-Warteschlangen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmCallbacks : EcucParamConfContainerDef</strong>: Container für Callback-Benachrichtigungen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Container sind über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+container</code> an die zentrale Moduldefinition <code>Csm</code> gebunden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodell- und Konfigurationsstruktur dar. Es enthält kein dynamisches Laufzeitverhalten, keine Zustandsübergänge und keine Aufrufsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kompositionsbeziehungen und Multiplizitäten definieren normative Validierungsregeln für AUTOSAR-ECU-Konfigurationswerkzeuge (ECUC Generator / Parser):</p>\n<ul class=\"fig-list\"><li>Das Modul <code>Csm</code> ist optional bis maximal einfach konfigurierbar (<code>0..1</code>).\n</li><li>Die Container <code>CsmJobs</code>, <code>CsmKeys</code>, <code>CsmQueues</code> und <code>CsmCallbacks</code> sind jeweils optional und maximal einfach (<code>0..1</code>).\n</li><li>Der Container <code>CsmPrimitives</code> erlaubt eine beliebige Anzahl von Instanzen (<code>0..*</code>).\n</li><li>Konfigurationsgeneratoren müssen die hierarchische Struktur und Kardinalitätsvorgaben bei der Erzeugung und Validierung von Konfigurations-XML-Dateien (<code>.arxml</code>) zwingend durchsetzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c0dc6c6f3a776287", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Konfigurations-Metamodells (ECUC Parameter Definition) für das BSW-Modul Crypto Service Manager (CSM) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die modulare Gliederung der BSW-Konfiguration über Container-Definitionen (<code>EcucParamConfContainerDef</code>) und deren hierarchische Komposition unterhalb der Moduldefinition (<code>EcucModuleDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Csm: EcucModuleDef</strong>: Wurzel-Moduldefinition des Crypto Service Managers mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmGeneral: EcucParamConfContainerDef</strong>: Allgemeiner Konfigurationscontainer (ohne explizit angegebene Multiplizität).\n</li><li><strong>CsmJobs: EcucParamConfContainerDef</strong>: Container zur Definition kryptografischer Jobs mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmKeys: EcucParamConfContainerDef</strong>: Container für Schlüsseldefinitionen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmPrimitives: EcucParamConfContainerDef</strong>: Container für kryptografische Primitive mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>CsmQueues: EcucParamConfContainerDef</strong>: Container für CSM-Warteschlangen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmCallbacks: EcucParamConfContainerDef</strong>: Container für Callback-Benachrichtigungen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmInOutRedirections: EcucParamConfContainerDef</strong>: Container für Ein-/Ausgabe-Umleitungen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Container sind über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+container</code> an die zentrale Moduldefinition <code>Csm</code> gebunden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodell- und Konfigurationsstruktur dar. Es enthält kein dynamisches Laufzeitverhalten, keine Zustandsübergänge und keine Aufrufsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kompositionsbeziehungen und Multiplizitäten definieren normative Validierungsregeln für AUTOSAR-ECU-Konfigurationswerkzeuge (ECUC Generator / Parser):</p>\n<ul class=\"fig-list\"><li>Das Modul <code>Csm</code> ist optional bis maximal einfach konfigurierbar (<code>0..1</code>).\n</li><li>Die Container <code>CsmJobs</code>, <code>CsmKeys</code>, <code>CsmQueues</code>, <code>CsmCallbacks</code> und <code>CsmInOutRedirections</code> sind jeweils optional und maximal einfach (<code>0..1</code>).\n</li><li>Der Container <code>CsmPrimitives</code> erlaubt eine beliebige Anzahl von Instanzen (<code>0..*</code>).\n</li><li>Konfigurationsgeneratoren müssen die hierarchische Struktur und Kardinalitätsvorgaben bei der Erzeugung und Validierung von Konfigurations-XML-Dateien (<code>.arxml</code>) zwingend durchsetzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ada752daa1d888bf", "releases": ["R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Konfigurations-Metamodells (ECUC Parameter Definition) für das BSW-Modul Crypto Service Manager (CSM) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die modulare Gliederung der BSW-Konfiguration über Container-Definitionen (<code>EcucParamConfContainerDef</code>) und deren hierarchische Komposition unterhalb der Moduldefinition (<code>EcucModuleDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Csm: EcucModuleDef</strong>: Wurzel-Moduldefinition des Crypto Service Managers mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmGeneral: EcucParamConfContainerDef</strong>: Allgemeiner Konfigurationscontainer mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmJobs: EcucParamConfContainerDef</strong>: Container zur Definition kryptografischer Jobs mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmKeys: EcucParamConfContainerDef</strong>: Container für Schlüsseldefinitionen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmPrimitives: EcucParamConfContainerDef</strong>: Container für kryptografische Primitive mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>CsmQueues: EcucParamConfContainerDef</strong>: Container für CSM-Warteschlangen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmCallbacks: EcucParamConfContainerDef</strong>: Container für Callback-Benachrichtigungen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li><strong>CsmInOutRedirections: EcucParamConfContainerDef</strong>: Container für Ein-/Ausgabe-Umleitungen mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Container sind über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+container</code> an die zentrale Moduldefinition <code>Csm</code> gebunden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodell- und Konfigurationsstruktur dar. Es enthält kein dynamisches Laufzeitverhalten, keine Zustandsübergänge und keine Aufrufsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kompositionsbeziehungen und Multiplizitäten definieren normative Validierungsregeln für AUTOSAR-ECU-Konfigurationswerkzeuge (ECUC Generator / Parser):</p>\n<ul class=\"fig-list\"><li>Das Modul <code>Csm</code> ist optional bis maximal einfach konfigurierbar (<code>0..1</code>).\n</li><li>Der Container <code>CsmGeneral</code> ist verpflichtend genau einfach zu konfigurieren (<code>1..1</code>), sobald das Modul vorhanden ist.\n</li><li>Die Container <code>CsmJobs</code>, <code>CsmKeys</code>, <code>CsmQueues</code>, <code>CsmCallbacks</code> und <code>CsmInOutRedirections</code> sind jeweils optional und maximal einfach (<code>0..1</code>).\n</li><li>Der Container <code>CsmPrimitives</code> erlaubt eine beliebige Anzahl von Instanzen (<code>0..*</code>).\n</li><li>Konfigurationsgeneratoren müssen die hierarchische Struktur und Kardinalitätsvorgaben bei der Erzeugung und Validierung von Konfigurations-XML-Dateien (<code>.arxml</code>) zwingend durchsetzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-00d681f2ae9b1715", "to": "FIG-c0dc6c6f3a776287", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neuer Container <code>CsmInOutRedirections: EcucParamConfContainerDef</code> über eine Kompositionsbeziehung <code>+container</code> an <code>Csm: EcucModuleDef</code> angebunden mit Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li></ul>"}, {"from": "FIG-c0dc6c6f3a776287", "to": "FIG-ada752daa1d888bf", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Container <code>CsmGeneral: EcucParamConfContainerDef</code>: Kardinalität explizit auf <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> festgelegt (bisher keine Multiplizitätsangabe im Diagramm).\n</li></ul>"}]};
